import{_ as e,o,c as i,a2 as r}from"./chunks/framework.CgxQ0r6v.js";const p=JSON.parse('{"title":"Manual de Estudio Profundo: Evaluación 1","description":"","frontmatter":{},"headers":[],"relativePath":"materias/Proyecto_Sociotecnologico_I/documentacion/I-I/Lectura_Catedra_Evaluacion_1.md","filePath":"materias/Proyecto_Sociotecnologico_I/documentacion/I-I/Lectura_Catedra_Evaluacion_1.md"}'),n={name:"materias/Proyecto_Sociotecnologico_I/documentacion/I-I/Lectura_Catedra_Evaluacion_1.md"};function t(c,a,s,d,l,u){return o(),i("div",null,[...a[0]||(a[0]=[r('<h1 id="manual-de-estudio-profundo-evaluacion-1" tabindex="-1">Manual de Estudio Profundo: Evaluación 1 <a class="header-anchor" href="#manual-de-estudio-profundo-evaluacion-1" aria-label="Permalink to &quot;Manual de Estudio Profundo: Evaluación 1&quot;">​</a></h1><h2 id="materia-proyecto-sociotecnologico-trayecto-i" tabindex="-1">Materia: Proyecto Sociotecnológico (Trayecto I) <a class="header-anchor" href="#materia-proyecto-sociotecnologico-trayecto-i" aria-label="Permalink to &quot;Materia: Proyecto Sociotecnológico (Trayecto I)&quot;">​</a></h2><h3 id="eje-tematico-la-comunidad-como-resultado-de-la-universidad" tabindex="-1">Eje Temático: La comunidad como resultado de la universidad <a class="header-anchor" href="#eje-tematico-la-comunidad-como-resultado-de-la-universidad" aria-label="Permalink to &quot;Eje Temático: La comunidad como resultado de la universidad&quot;">​</a></h3><hr><h2 id="🧭-introduccion-la-tecnologia-al-servicio-de-la-sociedad" tabindex="-1">🧭 Introducción: La Tecnología al Servicio de la Sociedad <a class="header-anchor" href="#🧭-introduccion-la-tecnologia-al-servicio-de-la-sociedad" aria-label="Permalink to &quot;🧭 Introducción: La Tecnología al Servicio de la Sociedad&quot;">​</a></h2><p>Cuando pensamos en informática, solemos visualizar pantallas, códigos y servidores en cuartos oscuros. Sin embargo, en el Programa Nacional de Formación en Informática (PNFI), la tecnología no es un fin en sí misma, sino un <strong>medio</strong> para resolver problemas reales de las personas.</p><p>El <strong>Proyecto Sociotecnológico (PST)</strong> es el corazón de tu formación. No se trata solo de aprender a programar o a reparar una computadora en un laboratorio aislado; se trata de salir al mundo real, conocer a la gente, entender sus necesidades y aplicar tus conocimientos técnicos para mejorar su calidad de vida. En este trayecto, dejarás de ser un simple estudiante de aula para convertirte en un <strong>agente de cambio social</strong>.</p><hr><h2 id="🏛️-capitulo-i-entendiendo-nuestro-entorno-sociedad-y-comunidad" tabindex="-1">🏛️ CAPÍTULO I: Entendiendo nuestro entorno (Sociedad y Comunidad) <a class="header-anchor" href="#🏛️-capitulo-i-entendiendo-nuestro-entorno-sociedad-y-comunidad" aria-label="Permalink to &quot;🏛️ CAPÍTULO I: Entendiendo nuestro entorno (Sociedad y Comunidad)&quot;">​</a></h2><p>Para poder ayudar a un grupo de personas, primero debemos entender cómo se organizan.</p><h3 id="_1-1-¿que-es-la-sociedad" tabindex="-1">1.1 ¿Qué es la Sociedad? <a class="header-anchor" href="#_1-1-¿que-es-la-sociedad" aria-label="Permalink to &quot;1.1 ¿Qué es la Sociedad?&quot;">​</a></h3><p>La <strong>Sociedad</strong> es un concepto amplio. Es el conjunto de individuos que conviven en un mismo territorio bajo un esquema de organización, compartiendo lazos económicos, políticos y culturales. <em>Analogía:</em> Piensa en la sociedad como un gran sistema operativo (como Windows o Linux). Es la estructura global que permite que todo funcione, con sus leyes y normas generales, pero es demasiado inmensa para abarcarla toda de una vez.</p><h3 id="_1-2-¿que-es-la-comunidad" tabindex="-1">1.2 ¿Qué es la Comunidad? <a class="header-anchor" href="#_1-2-¿que-es-la-comunidad" aria-label="Permalink to &quot;1.2 ¿Qué es la Comunidad?&quot;">​</a></h3><p>La <strong>Comunidad</strong> es un subconjunto más íntimo de la sociedad. Es un grupo de personas que viven en un área geográfica específica (un barrio, un sector, un caserío) o que comparten intereses muy particulares (la comunidad educativa de una escuela, la comunidad de un ambulatorio). Los miembros de una comunidad tienen un sentido de pertenencia, comparten problemas comunes y, por lo general, se conocen o interactúan frecuentemente. <em>Analogía:</em> Si la sociedad es el sistema operativo, la comunidad es una carpeta específica donde guardas los archivos de un proyecto vital. Es un entorno delimitado, con características propias, donde puedes actuar directamente.</p><div class="important custom-block github-alert"><p class="custom-block-title">IMPORTANT</p><p><strong>Tu objetivo en el Trayecto I no es resolver los problemas de toda la sociedad venezolana, sino enfocarte en una comunidad específica.</strong> Al resolver un problema local (como reparar los equipos del ambulatorio de tu sector o crear un inventario para el consejo comunal), estás sumando a la solución global.</p></div><hr><h2 id="🧩-capitulo-ii-la-universidad-como-motor-de-cambio" tabindex="-1">🧩 CAPÍTULO II: La Universidad como Motor de Cambio <a class="header-anchor" href="#🧩-capitulo-ii-la-universidad-como-motor-de-cambio" aria-label="Permalink to &quot;🧩 CAPÍTULO II: La Universidad como Motor de Cambio&quot;">​</a></h2><p>En el modelo tradicional, la universidad era vista como un &quot;castillo&quot; donde los sabios estudiaban y, al graduarse, iban a trabajar a las empresas. El PNFI rompe este esquema.</p><h3 id="_2-1-el-nuevo-rol-de-la-universidad" tabindex="-1">2.1 El Nuevo Rol de la Universidad <a class="header-anchor" href="#_2-1-el-nuevo-rol-de-la-universidad" aria-label="Permalink to &quot;2.1 El Nuevo Rol de la Universidad&quot;">​</a></h3><p>La universidad ya no está aislada; la comunidad es ahora una extensión del salón de clases. <strong>La comunidad es el resultado de la universidad, y la universidad es el reflejo de la comunidad.</strong></p><p>Según el <strong>Reglamento para la administración del Proyecto Socio Integrador/Tecnológico</strong>, los proyectos tienen un carácter sociocomunitario de carácter <strong>obligatorio</strong>. Esto significa que tu aprendizaje está condicionado a la generación de un impacto positivo en el entorno.</p><h3 id="_2-2-la-informatica-aplicada" tabindex="-1">2.2 La Informática Aplicada <a class="header-anchor" href="#_2-2-la-informatica-aplicada" aria-label="Permalink to &quot;2.2 La Informática Aplicada&quot;">​</a></h3><p>En la UPTT &quot;Mario Briceño Iragorry&quot;, nos regimos por líneas de investigación claras. Para el Trayecto I, tus acciones se enmarcarán principalmente dentro de la <strong>Informática Aplicada</strong>. Esto incluye, por ejemplo:</p><ul><li><strong>Soporte Técnico a Usuarios y Equipos:</strong> Diagnosticar y reparar equipos de computación en instituciones comunitarias (escuelas, ambulatorios) que no tienen presupuesto para ello.</li><li><strong>Alfabetización Tecnológica:</strong> Enseñar a los miembros de la comunidad a usar herramientas ofimáticas o sistemas gubernamentales.</li></ul><hr><h2 id="🏗️-capitulo-iii-el-proyecto-sociotecnologico-pst" tabindex="-1">🏗️ CAPÍTULO III: El Proyecto Sociotecnológico (PST) <a class="header-anchor" href="#🏗️-capitulo-iii-el-proyecto-sociotecnologico-pst" aria-label="Permalink to &quot;🏗️ CAPÍTULO III: El Proyecto Sociotecnológico (PST)&quot;">​</a></h2><h3 id="_3-1-¿que-es-el-pst" tabindex="-1">3.1 ¿Qué es el PST? <a class="header-anchor" href="#_3-1-¿que-es-el-pst" aria-label="Permalink to &quot;3.1 ¿Qué es el PST?&quot;">​</a></h3><p>Como dicta el Reglamento (Art. 2), el PSI/T es una <em>unidad curricular de integración de saberes y contraste entre teoría y práctica</em>. Es decir, aquí aplicarás lo que aprendes en Arquitectura del Computador, Algorítmica y Programación, y Formación Sociocrítica, todo al mismo tiempo.</p><h3 id="_3-2-el-esquema-de-trabajo-el-portafolio" tabindex="-1">3.2 El Esquema de Trabajo (El Portafolio) <a class="header-anchor" href="#_3-2-el-esquema-de-trabajo-el-portafolio" aria-label="Permalink to &quot;3.2 El Esquema de Trabajo (El Portafolio)&quot;">​</a></h3><p>Para llevar un control riguroso de tu trabajo, no basta con &quot;ir a la comunidad y arreglar una PC&quot;. Debes documentar científicamente tu proceso. Para ello, utilizarás:</p><ol><li><strong>El Portafolio (Físico y Digital):</strong> Es tu bitácora de vuelo. Aquí archivarás cada carta de aceptación, cada encuesta realizada, cada foto del trabajo de campo y cada minuta de reunión. Es la evidencia física de tu esfuerzo.</li><li><strong>El Informe de Proyecto:</strong> Es el documento académico estructurado (que sigue las normas formales de la UPTT) donde sistematizas toda la experiencia. Este informe será tu boleto para la aprobación del trayecto y requerirá una defensa final ante la comunidad (Universitaria y beneficiaria).</li></ol><div class="tip custom-block github-alert"><p class="custom-block-title">TIP</p><p><strong>El Secreto del Éxito:</strong> Un excelente proyecto tecnológico fracasa si no está bien documentado. Acostúmbrate desde el primer día a guardar respaldos digitales, tomar fotografías (con permiso) de tus interacciones en la comunidad y solicitar firmas de asistencia en cada reunión que realices con los líderes comunitarios.</p></div><p>En nuestra próxima evaluación, daremos el primer paso práctico: <strong>El Abordaje y el Diagnóstico Participativo</strong>. Aprenderemos cómo tocar la puerta de una comunidad sin ser invasivos y cómo descubrir sus verdaderas necesidades tecnológicas.</p>',33)])])}const g=e(n,[["render",t]]);export{p as __pageData,g as default};
